document.addEventListener('DOMContentLoaded', () => {
    const counters = document.querySelectorAll('[data-counter]');
  
    // Kurva easing sederhana (setara power1.out / power2.out)
    const easeOutCubic = (t) => 1 - Math.pow(1 - t, 3);
  
    const animateCounter = (el) => {
      const target = Number(el.dataset.targetVal);
      const startVal = Number(el.dataset.startVal);
      const decimalPlaces = Number(el.dataset.decimalPlaces) || 0;
      const duration = (parseFloat(el.dataset.duration) || 1.5) * 1000;
      const delay = (parseFloat(el.dataset.delay) || 0) * 1000;
  
      // Batalkan animasi lama jika elemen di-trigger ulang (data-once="false")
      if (el._rafId) cancelAnimationFrame(el._rafId);
      if (el._delayId) clearTimeout(el._delayId);
  
      const run = () => {
        const startTime = performance.now();
  
        const tick = (now) => {
          const elapsed = now - startTime;
          const progress = Math.min(elapsed / duration, 1);
          const eased = easeOutCubic(progress);
          const current = startVal + (target - startVal) * eased;
  
          el.textContent = current.toFixed(decimalPlaces);
  
          if (progress < 1) {
            el._rafId = requestAnimationFrame(tick);
          } else {
            el.textContent = target.toFixed(decimalPlaces);
          }
        };
  
        el._rafId = requestAnimationFrame(tick);
      };
  
      if (delay > 0) {
        el._delayId = setTimeout(run, delay);
      } else {
        run();
      }
    };
  
    // Siapkan nilai awal tiap elemen
    const validCounters = [];
    counters.forEach((el) => {
      const raw = el.textContent.trim();
      const cleaned = raw.replace(/[^0-9.-]/g, '');
      const target = Number(cleaned);
  
      if (!cleaned || Number.isNaN(target)) return;
  
      const parsedStart = parseFloat(el.dataset.startVal);
      const startVal = Number.isFinite(parsedStart) ? parsedStart : 0;
  
      const startDecimals = (String(startVal).split('.')[1] || '').length;
      const targetDecimals = (cleaned.split('.')[1] || '').length;
      const decimalPlaces = Math.max(startDecimals, targetDecimals);
  
      el.dataset.targetVal = String(target);
      el.dataset.startVal = String(startVal);
      el.dataset.decimalPlaces = String(decimalPlaces);
      el.textContent = startVal.toFixed(decimalPlaces);
  
      validCounters.push(el);
    });
  
    // Pantau visibilitas elemen saat scroll
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          const el = entry.target;
          const once = el.dataset.once !== 'false';
  
          if (entry.isIntersecting) {
            animateCounter(el);
            if (once) {
              observer.unobserve(el);
            }
          } else if (!once) {
            // Reset ke angka awal saat keluar layar jika animasi bisa berulang
            if (el._rafId) cancelAnimationFrame(el._rafId);
            if (el._delayId) clearTimeout(el._delayId);
            const startVal = Number(el.dataset.startVal) || 0;
            const decimalPlaces = Number(el.dataset.decimalPlaces) || 0;
            el.textContent = startVal.toFixed(decimalPlaces);
          }
        });
      },
      {
        threshold: 0.2, // Mulai saat sekitar 20% elemen terlihat di layar
      }
    );
  
    validCounters.forEach((el) => observer.observe(el));
  });